import type { FC } from 'react';

interface Product {
  id: number;
  name: string;
  price: number;
}

const CartCheckout: FC = () => {
  const [cartItems, setCartItems] = React.useState<Product[]>([]);
  const [totalPrice, setTotalPrice] = React.useState<number>(0);
  const [paymentInfo, setPaymentInfo] = React.useState<{ cardNumber: string; cvv: string; expirationDate: string }>({ cardNumber: '', cvv: '', expirationDate: '' });

  const fetchProducts = async () => {
    try {
      const response = await fetch('/api/catalog-api/products');
      const products: Product[] = await response.json();
      setCartItems(products);
      calculateTotal(products);
    } catch (error) {
      console.error('Failed to fetch products:', error);
    }
  };

  const calculateTotal = (products: Product[]) => {
    const total = products.reduce((acc, product) => acc + product.price, 0);
    setTotalPrice(total);
  };

  const handleCheckout = async () => {
    try {
      const orderResponse = await fetch('/api/orders-api/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ items: cartItems }),
      });

      if (!orderResponse.ok) {
        throw new Error('Order creation failed');
      }

      const orderId = await orderResponse.text();

      const paymentResponse = await fetch('/api/payment-gateway-adapter/charge', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ orderId, cardNumber: paymentInfo.cardNumber, cvv: paymentInfo.cvv, expirationDate: paymentInfo.expirationDate }),
      });

      if (!paymentResponse.ok) {
        throw new Error('Payment failed');
      }

      alert('Order placed successfully!');
    } catch (error) {
      console.error('Checkout failed:', error);
      alert('Checkout failed. Please try again.');
    }
  };

  React.useEffect(() => {
    fetchProducts();
  }, []);

  return (
    <div>
      <h1>Cart</h1>
      <ul>
        {cartItems.map(item => (
          <li key={item.id}>{item.name} - ${item.price}</li>
        ))}
      </ul>
      <p>Total Price: ${totalPrice}</p>
      <h2>Payment Information</h2>
      <input
        type='text'
        placeholder='Card Number'
        value={paymentInfo.cardNumber}
        onChange={(e) => setPaymentInfo({ ...paymentInfo, cardNumber: e.target.value })}
      />
      <input
        type='text'
        placeholder='CVV'
        value={paymentInfo.cvv}
        onChange={(e) => setPaymentInfo({ ...paymentInfo, cvv: e.target.value })}
      />
      <input
        type='text'
        placeholder='Expiration Date'
        value={paymentInfo.expirationDate}
        onChange={(e) => setPaymentInfo({ ...paymentInfo, expirationDate: e.target.value })}
      />
      <button onClick={handleCheckout}>Checkout</button>
    </div>
  );
};

export { CartCheckout };

import type { FC } from 'react';

interface Product {
  id: number;
  name: string;
  price: number;
}

const AdminProductPanel: FC = () => {
  const [products, setProducts] = React.useState<Product[]>([]);
  const [newProductName, setNewProductName] = React.useState('');
  const [newProductPrice, setNewProductPrice] = React.useState(0);

  React.useEffect(() => {
    fetch('/api/catalog-api/products')
      .then(response => response.json())
      .then(data => setProducts(data));
  }, []);

  const handleAddProduct = async () => {
    const newProduct = {
      name: newProductName,
      price: Number(newProductPrice),
    };

    await fetch('/api/catalog-api/products', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(newProduct),
    });

    setProducts([...products, newProduct]);
    setNewProductName('');
    setNewProductPrice(0);
  };

  const handleEditProduct = async (id: number, newName: string, newPrice: number) => {
    await fetch(`/api/catalog-api/products/${id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ name: newName, price: newPrice }),
    });

    setProducts(products.map(product => (
      product.id === id ? { ...product, name: newName, price: newPrice } : product
    )));
  };

  const handleDeleteProduct = async (id: number) => {
    await fetch(`/api/catalog-api/products/${id}`, {
      method: 'DELETE',
    });

    setProducts(products.filter(product => product.id !== id));
  };

  return (
    <div>
      <h1>Admin Product Panel</h1>
      <input
        type='text'
        placeholder='New Product Name'
        value={newProductName}
        onChange={(e) => setNewProductName(e.target.value)}
      />
      <input
        type='number'
        placeholder='New Product Price'
        value={newProductPrice}
        onChange={(e) => setNewProductPrice(Number(e.target.value))}
      />
      <button onClick={handleAddProduct}>Add Product</button>
      <ul>
        {products.map(product => (
          <li key={product.id}>
            {product.name} - ${product.price}
            <button onClick={() => handleEditProduct(product.id, 'Updated Name', 99)}>Edit</button>
            <button onClick={() => handleDeleteProduct(product.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export { AdminProductPanel };

import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync('./finance.db');

interface Transaction {
  id: number;
  amount: number;
  merchant: string;
  date: Date;
  category: string;
}

function createTable(): void {
  const sql = `
    CREATE TABLE IF NOT EXISTS transactions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      amount REAL NOT NULL,
      merchant TEXT NOT NULL,
      date DATETIME NOT NULL,
      category TEXT NOT NULL
    );
  `;
  db.exec(sql);
}

function insertTransaction(amount: number, merchant: string, date: Date, category: string): number {
  const sql = 'INSERT INTO transactions (amount, merchant, date, category) VALUES (?, ?, ?, ?)';
  const stmt = db.prepare(sql);
  const result = stmt.run(amount, merchant, date.toISOString(), category);
  return result.lastInsertRowid as number;
}

function getTransactions(): Transaction[] {
  const sql = 'SELECT * FROM transactions';
  const stmt = db.prepare(sql);
  const rows = stmt.all() as unknown as Record<string, any>[];
  return rows.map(row => ({
    id: row.id as number,
    amount: row.amount as number,
    merchant: row.merchant as string,
    date: new Date(row.date as string),
    category: row.category as string
  }));
}

function getTransactionById(id: number): Transaction | null {
  const sql = 'SELECT * FROM transactions WHERE id = ?';
  const stmt = db.prepare(sql);
  const row = stmt.get(id) as unknown as Record<string, any> | undefined;
  if (!row) return null;
  return {
    id: row.id as number,
    amount: row.amount as number,
    merchant: row.merchant as string,
    date: new Date(row.date as string),
    category: row.category as string
  };
}

export { db, createTable, insertTransaction, getTransactions, getTransactionById };

