export { TransactionList };

import type { FC } from 'react';

interface Transaction {
  id: number;
  amount: number;
  category: string;
}

const calculateSpendingPerCategory = (transactions: Transaction[]): { [category: string]: number } => {
  const spending: { [category: string]: number } = {};
  transactions.forEach(transaction => {
    if (!spending[transaction.category]) {
      spending[transaction.category] = 0;
    }
    spending[transaction.category] += transaction.amount;
  });
  return spending;
};

const fetchTransactions = async (): Promise<Transaction[]> => {
  const response = await fetch('/api/categorisation-api/transactions');
  if (!response.ok) {
    throw new Error('Failed to fetch transactions');
  }
  return await response.json();
};

const BudgetOverview: FC = () => {
  const [transactions, setTransactions] = React.useState<Transaction[]>([]);
  const [loading, setLoading] = React.useState<boolean>(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const transactionsData = await fetchTransactions();
        setTransactions(transactionsData);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  const spendingPerCategory = calculateSpendingPerCategory(transactions);

  return (
    <div>
      <h1>Budget Overview</h1>
      <ul>
        {Object.entries(spendingPerCategory).map(([category, amount]) => (
          <li key={category}>{`${category}: $${amount.toFixed(2)}`}</li>
        ))}
      </ul>
    </div>
  );
};

export { BudgetOverview };

