const ScheduleBuilder: FC = () => {
  const [schedules, setSchedules] = React.useState<Schedule[]>([]);
  const [newSchedule, setNewSchedule] = React.useState<Schedule>({ deviceId: 1, startTime: new Date(), endTime: new Date(), action: '' });

  const fetchSchedules = async () => {
    try {
      const response = await fetch('/api/scheduler-service/schedules');
      const data = await response.json();
      setSchedules(data);
    } catch (error) {
      console.error('Error fetching schedules:', error);
    }
  };

  const createSchedule = async () => {
    try {
      const response = await fetch('/api/scheduler-service/schedules', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newSchedule),
      });
      if (response.ok) {
        fetchSchedules();
        setNewSchedule({ deviceId: 1, startTime: new Date(), endTime: new Date(), action: '' });
      } else {
        console.error('Error creating schedule');
      }
    } catch (error) {
      console.error('Error creating schedule:', error);
    }
  };

  const updateSchedule = async (id: number) => {
    try {
      const response = await fetch(`/api/scheduler-service/schedules/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newSchedule),
      });
      if (response.ok) {
        fetchSchedules();
      } else {
        console.error('Error updating schedule');
      }
    } catch (error) {
      console.error('Error updating schedule:', error);
    }
  };

  const deleteSchedule = async (id: number) => {
    try {
      const response = await fetch(`/api/scheduler-service/schedules/${id}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        fetchSchedules();
      } else {
        console.error('Error deleting schedule');
      }
    } catch (error) {
      console.error('Error deleting schedule:', error);
    }
  };

  React.useEffect(() => {
    fetchSchedules();
  }, []);

  return (
    <div>
      <h1>Schedule Builder</h1>
      <form onSubmit={(e) => { e.preventDefault(); newSchedule.id ? updateSchedule(newSchedule.id) : createSchedule(); }}>
        <input
          type='number'
          value={newSchedule.deviceId}
          onChange={(e) => setNewSchedule({ ...newSchedule, deviceId: Number(e.target.value) })}
        />
        <input
          type='datetime-local'
          value={newSchedule.startTime.toISOString().slice(0, 16)}
          onChange={(e) => setNewSchedule({ ...newSchedule, startTime: new Date(e.target.value) })}
        />
        <input
          type='datetime-local'
          value={newSchedule.endTime.toISOString().slice(0, 16)}
          onChange={(e) => setNewSchedule({ ...newSchedule, endTime: new Date(e.target.value) })}
        />
        <input
          type='text'
          value={newSchedule.action}
          onChange={(e) => setNewSchedule({ ...newSchedule, action: e.target.value })}
        />
        <button type='submit'>Save</button>
      </form>
      <ul>
        {schedules.map((schedule) => (
          <li key={schedule.id}>
            {schedule.startTime.toLocaleString()} - {schedule.endTime.toLocaleString()} - {schedule.action}
            <button onClick={() => setNewSchedule(schedule)}>Edit</button>
            <button onClick={() => deleteSchedule(schedule.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

