    fetch(`/api/claims-api/claims/${claimId}/status`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ status: 'approved' })
    }).then(() => {
      // Refresh claims list
      fetch('/api/claims-api/claims')
        .then(response => response.json())
        .then(data => setClaims(data));
    });
  };

  const handleDenyClaim = (claimId: number) => {
    fetch(`/api/claims-api/claims/${claimId}/status`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ status: 'denied' })
    }).then(() => {
      // Refresh claims list
      fetch('/api/claims-api/claims')
        .then(response => response.json())
        .then(data => setClaims(data));
    });
  };

  return (
    <div>
      <h1>Adjuster Review Queue</h1>
      <ul>
        {claims.map(claim => (
          <li key={claim.id}>
            Policyholder ID: {claim.policyholderId}, Amount: ${claim.amount}, Status: {claim.status}
            <button onClick={() => handleApproveClaim(claim.id)}>Approve</button>
            <button onClick={() => handleDenyClaim(claim.id)}>Deny</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

