    CREATE TABLE IF NOT EXISTS stock_levels (
      sku TEXT PRIMARY KEY,
      location_id INTEGER,
      current_quantity INTEGER,
      reorder_threshold INTEGER
    )
  `;
  db.exec(sql);
}

function insertStockLevel(stockLevel: StockLevel): void {
  const sql = 'INSERT INTO stock_levels (sku, location_id, current_quantity, reorder_threshold) VALUES (?, ?, ?, ?)';
