function updateStockLevel(sku: string, stockLevel: Partial<StockLevel>): void {
  const setClause = Object.keys(stockLevel)
    .map(key => `${key} = ?`) // Assuming all properties are optional
    .join(', ');
  const params = [setClause, ...Object.values(stockLevel), sku];
  const sql = `UPDATE stock_levels SET ${setClause} WHERE sku = ?`;
  db.prepare(sql).run(params);
}

function getStockLevel(sku: string): StockLevel | null {
  const sql = 'SELECT * FROM stock_levels WHERE sku = ?';
  const result = db.prepare(sql).get(sku) as unknown as StockLevel | null;
  return result;
}

