import type { FC } from "react";

interface Shift {
  id: number;
  title: string;
  date: string;
  time: string;
  location: string;
  capacity: number;
  signUpCount: number;
}

const ShiftBoard: FC = () => {
  const fetchShifts = async (): Promise<Shift[]> => {
    const response = await fetch("/api/shifts-api/shifts");
    if (!response.ok) {
      throw new Error("Failed to fetch shifts");
    }
    return await response.json();
  };

  const handleSignUp = async (shiftId: number) => {
    try {
      await fetch(`/api/shifts-api/signups`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ shiftId }),
      });
      alert("Sign up successful!");
    } catch (error) {
      console.error("Error signing up:", error);
      alert("Failed to sign up.");
    }
  };

  return (
    <div>
      <h1>Volunteer Shifts</h1>
      <ul>
        {fetchShifts().then(shifts =>
          shifts.map(shift => (
            <li key={shift.id}>
              <strong>{shift.title}</strong> - {shift.date} {shift.time} at {shift.location}
              <p>Capacity: {shift.capacity}, Sign-ups: {shift.signUpCount}</p>
