import { DatabaseSync } from "node:sqlite";

interface ClockEvent {
  employee_id: number;
  event_type: 'in' | 'out';
  timestamp: Date;
}

const db = new DatabaseSync('timesheet.db');

function createTable(): void {
  const sql = `CREATE TABLE IF NOT EXISTS clock_events (
    employee_id INTEGER,
    event_type TEXT CHECK (event_type IN ('in', 'out')),
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
  )`;
  db.exec(sql);
}

function insertClockEvent(employeeId: number, eventType: 'in' | 'out'): void {
  const sql = 'INSERT INTO clock_events (employee_id, event_type) VALUES (?, ?)';
  db.prepare(sql).run(employeeId, eventType);
}

function getClockEventsByEmployeeId(employeeId: number): ClockEvent[] {
  const sql = 'SELECT * FROM clock_events WHERE employee_id = ?';
  const stmt = db.prepare(sql);
  return stmt.all(employeeId) as unknown as ClockEvent[];
}

export { db, createTable, insertClockEvent, getClockEventsByEmployeeId };

import type { FC } from "react";

interface ClockInOutWidgetProps {
  employeeId: string;
}

const ClockInOutWidget: FC<ClockInOutWidgetProps> = ({ employeeId }) => {
  const [isClockingIn, setIsClockingIn] = React.useState(true);
  const [clockTime, setClockTime] = React.useState<Date | null>(null);

  const handleClockEvent = async () => {
    try {
      const response = await fetch(`/api/timesheets-api/clock-event`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          employeeId,
          clockTime: clockTime ? clockTime.toISOString() : undefined,
          isClockingIn
        })
      });

      if (!response.ok) {
        throw new Error('Failed to record clock event');
      }

      setIsClockingIn(!isClockingIn);
      setClockTime(isClockingIn ? new Date() : null);
    } catch (error) {
      console.error('Error recording clock event:', error);
    }
  };

  return (
    <div>
      <button onClick={handleClockEvent}>{isClockingIn ? 'Clock In' : 'Clock Out'}</button>
      {clockTime && <p>{isClockingIn ? 'Clock In Time:' : 'Clock Out Time:'} {clockTime.toLocaleString()}</p>}
    </div>
  );
};

export { ClockInOutWidget };

