import { DatabaseSync } from "node:sqlite";

interface Reservation {
  employeeId: number;
  date: string;
  spotNumber: number;
}

const db = new DatabaseSync('reservations.db');

function createTable(): void {
  const sql = `CREATE TABLE IF NOT EXISTS reservations (
    employeeId INTEGER,
    date TEXT,
    spotNumber INTEGER
  )`;
  db.exec(sql);
}

function insertReservation(reservation: Reservation): void {
  const sql = 'INSERT INTO reservations (employeeId, date, spotNumber) VALUES (?, ?, ?)';
  db.prepare(sql).run(reservation.employeeId, reservation.date, reservation.spotNumber);
}

function getReservationsByDate(date: string): Reservation[] {
  const sql = 'SELECT * FROM reservations WHERE date = ?';
  const stmt = db.prepare(sql);
  return stmt.all(date) as unknown as Reservation[];
}

function deleteReservation(employeeId: number, date: string): void {
  const sql = 'DELETE FROM reservations WHERE employeeId = ? AND date = ?';
  db.prepare(sql).run(employeeId, date);
}

export { db, createTable, insertReservation, getReservationsByDate, deleteReservation };

